-- 001_initial.sql
CREATE TABLE users ( id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member', created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE tasks ( id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'todo', predicted_hours REAL, actual_hours REAL, assignee_id INTEGER REFERENCES users(id) ON DELETE SET NULL, created_by INTEGER NOT NULL REFERENCES users(id), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP );
-- Индекс для быстрой фильтрации по статусу CREATE INDEX idx_tasks_status ON tasks(status);

-- 002_ml_tables.sql
ALTER TABLE tasks ADD COLUMN completed_at DATETIME;
UPDATE tasks SET completed_at = updated_at WHERE status = 'done' AND completed_at IS NULL;
ALTER TABLE tasks RENAME COLUMN actual_hours TO actual_spent_seconds; ALTER TABLE tasks RENAME COLUMN predicted_hours TO predicted_seconds;
-- Source-корпус (read-only, заполняется вручную) CREATE TABLE ml_source_tasks ( id INTEGER PRIMARY KEY AUTOINCREMENT, source_project_name TEXT NOT NULL, summary TEXT NOT NULL, description TEXT, actual_spent_seconds INTEGER NOT NULL, completed_at DATETIME, dataset_version TEXT NOT NULL DEFAULT 'v1' );
CREATE INDEX idx_ml_source_tasks_version ON ml_source_tasks(dataset_version);
-- Запуски обучения CREATE TABLE ml_training_runs ( id INTEGER PRIMARY KEY AUTOINCREMENT, mode TEXT NOT NULL, -- 'production' или 'evaluation' target_project_name TEXT, -- только для evaluation mode started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at DATETIME, status TEXT NOT NULL DEFAULT 'running', -- 'running', 'completed', 'failed' n_target_total INTEGER, n_target_train INTEGER, n_target_val INTEGER, n_target_test INTEGER, -- только для evaluation n_source INTEGER, config_json TEXT, best_candidate_id INTEGER, error_message TEXT );
-- Кандидаты моделей CREATE TABLE ml_model_candidates ( id INTEGER PRIMARY KEY AUTOINCREMENT, training_run_id INTEGER NOT NULL REFERENCES ml_training_runs(id) ON DELETE CASCADE, model_family TEXT NOT NULL, -- 'baseline', 'scratch_ridge', 'retrain_ridge' alpha REAL, target_share REAL, weight_summary REAL, weight_description REAL, weight_char REAL, r2_val REAL, medae_val REAL, mdape_val REAL, r2_test REAL, -- только для evaluation medae_test REAL, mdape_test REAL, artifact_path TEXT, is_selected INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE INDEX idx_ml_candidates_run ON ml_model_candidates(training_run_id);
-- Активная модель (одна запись, обновляется при смене модели) CREATE TABLE ml_active_model ( id INTEGER PRIMARY KEY CHECK (id = 1), model_candidate_id INTEGER NOT NULL REFERENCES ml_model_candidates(id), activated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, previous_candidate_id INTEGER );

use crate::errors::AppError;
use argon2::{
    Argon2,
    password_hash::{PasswordHasher, PasswordVerifier, phc::PasswordHash},
};
use chrono::{Duration, Utc};
use jsonwebtoken::{DecodingKey, EncodingKey, Header, Validation, decode, encode};
use serde::{Deserialize, Serialize};

#[derive(Debug, Serialize, Deserialize)]
pub struct Claims {
    pub sub: i64,     // user id
    pub role: String, // user role
    pub exp: i64,     // expiration time
}

pub fn hash_password(password: &str) -> Result {
    let argon2 = Argon2::default();

    argon2
        .hash_password(password.as_bytes())
        .map(|hash| hash.to_string())
        .map_err(|e| AppError::Internal(format!("Failed to hash password: {}", e)))
}

pub fn verify_password(password: &str, hash: &str) -> Result {
    let parsed_hash = PasswordHash::new(hash)
        .map_err(|e| AppError::Internal(format!("Invalid password hash: {}", e)))?;

    Ok(Argon2::default()
        .verify_password(password.as_bytes(), &parsed_hash)
        .is_ok())
}

pub fn create_token(user_id: i64, role: &str, secret: &str) -> Result {
    let expiration = Utc::now()
        .checked_add_signed(Duration::hours(24))
        .expect("valid timestamp")
        .timestamp();

    let claims = Claims {
        sub: user_id,
        role: role.to_string(),
        exp: expiration,
    };

    encode(
        &Header::default(),
        &claims,
        &EncodingKey::from_secret(secret.as_bytes()),
    )
    .map_err(|e| AppError::Internal(format!("Failed to create token: {}", e)))
}

pub fn verify_token(token: &str, secret: &str) -> Result {
    decode::(
        token,
        &DecodingKey::from_secret(secret.as_bytes()),
        &Validation::default(),
    )
    .map(|data| data.claims)
    .map_err(|_| AppError::Unauthorized)
}

#[derive(Clone)] pub struct Config { pub database_url: String, pub jwt_secret: String, pub host: String, pub port: u16, pub ml_service_url: String, pub admin_email: String, pub admin_password: String, }
impl Config { pub fn from_env() -> Self { dotenvy::dotenv().ok();
Self { database_url: std::env::var("DATABASE_URL") .unwrap_or_else(|_| "sqlite:data.db?mode=rwc".to_string()), jwt_secret: std::env::var("JWT_SECRET") .unwrap_or_else(|_| "super-secret-change-me".to_string()), host: std::env::var("HOST") .unwrap_or_else(|_| "127.0.0.1".to_string()), port: std::env::var("PORT") .unwrap_or_else(|_| "8080".to_string()) .parse() .expect("PORT must be a number"), ml_service_url: std::env::var("ML_SERVICE_URL") .unwrap_or_else(|_| "http://localhost:8000".to_string()), admin_email: std::env::var("ADMIN_EMAIL") .unwrap_or_else(|_| "admin@example.com".to_string()), admin_password: std::env::var("ADMIN_PASSWORD") .unwrap_or_else(|_| "adminpass123".to_string()), } } }

use actix_web::{HttpResponse, ResponseError};
use std::fmt;

#[derive(Debug)]
pub enum AppError {
    NotFound(String),
    BadRequest(String),
    Unauthorized,
    Forbidden,
    Internal(String),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::NotFound(msg) => write!(f, "Not found: {}", msg),
            AppError::BadRequest(msg) => write!(f, "Bad request: {}", msg),
            AppError::Unauthorized => write!(f, "Unauthorized"),
            AppError::Forbidden => write!(f, "Forbidden"),
            AppError::Internal(msg) => write!(f, "Internal error: {}", msg),
        }
    }
}

impl ResponseError for AppError {
    fn error_response(&self) -> HttpResponse {
        match self {
            AppError::NotFound(msg) => {
                HttpResponse::NotFound().json(serde_json::json!({"error": msg}))
            }
            AppError::BadRequest(msg) => {
                HttpResponse::BadRequest().json(serde_json::json!({"error": msg}))
            }
            AppError::Unauthorized => {
                HttpResponse::Unauthorized().json(serde_json::json!({"error": "Unauthorized"}))
            }
            AppError::Forbidden => {
                HttpResponse::Forbidden().json(serde_json::json!({"error": "Forbidden"}))
            }
            AppError::Internal(msg) => {
                tracing::error!("Internal error: {}", msg);
                HttpResponse::InternalServerError()
                    .json(serde_json::json!({"error": "Internal server error"}))
            }
        }
    }
}

impl From for AppError {
    fn from(e: sqlx::Error) -> Self {
        AppError::Internal(e.to_string())
    }
}

use actix_web::{web, HttpRequest, HttpResponse};
use sqlx::SqlitePool;
use crate::auth;
use crate::config::Config;
use crate::errors::AppError;
use crate::ml_client::MlClient;
use crate::models::{
    AuthenticatedUser, ChangePasswordRequest, CreateTaskRequest, CreateUserRequest,
    LoginRequest, UpdateTaskRequest,
};
use crate::services;

fn extract_user(req: &HttpRequest, config: &Config) -> Result {
    let header = req
        .headers()
        .get("Authorization")
        .and_then(|h| h.to_str().ok())
        .ok_or(AppError::Unauthorized)?;

    let token = header
        .strip_prefix("Bearer ")
        .ok_or(AppError::Unauthorized)?;

    let claims = auth::verify_token(token, &config.jwt_secret)?;

    Ok(AuthenticatedUser {
        id: claims.sub,
        role: claims.role,
    })
}

fn require_admin(user: &AuthenticatedUser) -> Result<(), AppError> {
    if user.role != "admin" {
        return Err(AppError::Forbidden);
    }
    Ok(())
}

// ============ Auth ============

pub async fn login(
    pool: web::Data,
    config: web::Data,
    req: web::Json,
) -> Result {
    let response = services::login(pool.get_ref(), req.into_inner(), &config.jwt_secret).await?;
    Ok(HttpResponse::Ok().json(response))
}

pub async fn change_password(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
    req: web::Json,
) -> Result {
    let user = extract_user(&http_req, &config)?;
    services::change_password(pool.get_ref(), user.id, req.into_inner()).await?;
    Ok(HttpResponse::Ok().json(serde_json::json!({"message": "Password changed"})))
}

pub async fn get_me(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
) -> Result {
    let auth_user = extract_user(&http_req, &config)?;
    let user = services::get_user_by_id(pool.get_ref(), auth_user.id).await?;
    Ok(HttpResponse::Ok().json(user))
}

// ============ Users ============

pub async fn create_user(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
    req: web::Json,
) -> Result {
    let user = extract_user(&http_req, &config)?;
    require_admin(&user)?;
    let new_user = services::create_user(pool.get_ref(), req.into_inner()).await?;
    Ok(HttpResponse::Created().json(new_user))
}

pub async fn get_all_users(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
) -> Result {
    let _ = extract_user(&http_req, &config)?;
    let users = services::get_all_users(pool.get_ref()).await?;
    Ok(HttpResponse::Ok().json(users))
}

pub async fn get_user(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
    path: web::Path,
) -> Result {
    let _ = extract_user(&http_req, &config)?;
    let user = services::get_user_by_id(pool.get_ref(), path.into_inner()).await?;
    Ok(HttpResponse::Ok().json(user))
}

pub async fn delete_user(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
    path: web::Path,
) -> Result {
    let user = extract_user(&http_req, &config)?;
    require_admin(&user)?;
    let user_id = path.into_inner();
    if user.id == user_id {
        return Err(AppError::BadRequest("Cannot delete yourself".to_string()));
    }
    services::delete_user(pool.get_ref(), user_id).await?;
    Ok(HttpResponse::NoContent().finish())
}

// ============ Tasks ============

pub async fn create_task(
    pool: web::Data,
    config: web::Data,
    ml_client: web::Data,
    http_req: HttpRequest,
    req: web::Json,
) -> Result {
    let user = extract_user(&http_req, &config)?;
    let task = services::create_task(pool.get_ref(), ml_client.get_ref(), req.into_inner(), user.id).await?;
    Ok(HttpResponse::Created().json(task))
}

pub async fn get_all_tasks(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
) -> Result {
    let _ = extract_user(&http_req, &config)?;
    let tasks = services::get_all_active_tasks(pool.get_ref()).await?;
    Ok(HttpResponse::Ok().json(tasks))
}

pub async fn get_my_tasks(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
) -> Result {
    let user = extract_user(&http_req, &config)?;
    let tasks = services::get_my_tasks(pool.get_ref(), user.id).await?;
    Ok(HttpResponse::Ok().json(tasks))
}

pub async fn get_task(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
    path: web::Path,
) -> Result {
    let _ = extract_user(&http_req, &config)?;
    let task = services::get_task_by_id(pool.get_ref(), path.into_inner()).await?;
    Ok(HttpResponse::Ok().json(task))
}

pub async fn update_task(
    pool: web::Data,
    config: web::Data,
    ml_client: web::Data,
    http_req: HttpRequest,
    path: web::Path,
    req: web::Json,
) -> Result {
    let _ = extract_user(&http_req, &config)?;
    let task = services::update_task(
        pool.get_ref(),
        ml_client.get_ref(),
        path.into_inner(),
        req.into_inner(),
    ).await?;
    Ok(HttpResponse::Ok().json(task))
}

pub async fn delete_task(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
    path: web::Path,
) -> Result {
    let _ = extract_user(&http_req, &config)?;
    services::delete_task(pool.get_ref(), path.into_inner()).await?;
    Ok(HttpResponse::NoContent().finish())
}

pub async fn archive_completed(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
) -> Result {
    let user = extract_user(&http_req, &config)?;
    require_admin(&user)?;
    let count = services::archive_completed(pool.get_ref()).await?;
    Ok(HttpResponse::Ok().json(serde_json::json!({"archived": count})))
}

// ============ Analytics ============

pub async fn get_analytics(
    pool: web::Data,
    config: web::Data,
    http_req: HttpRequest,
) -> Result {
    let _ = extract_user(&http_req, &config)?;
    let analytics = services::get_analytics(pool.get_ref()).await?;
    Ok(HttpResponse::Ok().json(analytics))
}

// ============ Admin ML ============

pub async fn get_ml_status(
    ml_client: web::Data,
    config: web::Data,
    http_req: HttpRequest,
) -> Result {
    let user = extract_user(&http_req, &config)?;
    require_admin(&user)?;
    let status = services::get_ml_status(ml_client.get_ref()).await?;
    Ok(HttpResponse::Ok().json(status))
}

pub async fn trigger_retrain(
    ml_client: web::Data,
    config: web::Data,
    http_req: HttpRequest,
) -> Result {
    let user = extract_user(&http_req, &config)?;
    require_admin(&user)?;
    let result = services::trigger_retrain(ml_client.get_ref()).await?;
    Ok(HttpResponse::Ok().json(result))
}

// ============ Routes ============

pub fn configure(cfg: &mut web::ServiceConfig) {
    cfg.service(
        web::scope("/api")
            // Auth
            .route("/login", web::post().to(login))
            .route("/change-password", web::post().to(change_password))
            .route("/me", web::get().to(get_me))
            // Users
            .route("/users", web::post().to(create_user))
            .route("/users", web::get().to(get_all_users))
            .route("/users/{id}", web::get().to(get_user))
            .route("/users/{id}", web::delete().to(delete_user))
            // Tasks
            .route("/tasks", web::post().to(create_task))
            .route("/tasks", web::get().to(get_all_tasks))
            .route("/tasks/my", web::get().to(get_my_tasks))
            .route("/tasks/{id}", web::get().to(get_task))
            .route("/tasks/{id}", web::put().to(update_task))
            .route("/tasks/{id}", web::delete().to(delete_task))
            // Analytics
            .route("/analytics", web::get().to(get_analytics))
            // Admin
            .route("/admin/archive", web::post().to(archive_completed))
            .route("/admin/ml/status", web::get().to(get_ml_status))
            .route("/admin/ml/retrain", web::post().to(trigger_retrain))
    );
}

use actix_cors::Cors;
use actix_web::{App, HttpResponse, HttpServer, middleware::Logger, web};
use sqlx::sqlite::SqlitePool;

mod auth;
mod config;
mod errors;
mod handlers;
mod ml_client;
mod models;
mod repository;
mod services;

async fn health() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "ok"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    tracing_subscriber::fmt::init();

    let config = config::Config::from_env();

    tracing::info!("Connecting to database...");
    let pool = SqlitePool::connect(&config.database_url)
        .await
        .expect("Failed to connect to database");

    services::init_admin(&pool, &config.admin_email, &config.admin_password)
        .await
        .expect("Failed to initialize admin");

    let ml_client = ml_client::MlClient::new(config.ml_service_url.clone());

    tracing::info!("Starting server at http://{}:{}", config.host, config.port);

    let config_data = config.clone();

    HttpServer::new(move || {
        let cors = Cors::permissive();

        App::new()
            .app_data(web::Data::new(pool.clone()))
            .app_data(web::Data::new(config_data.clone()))
            .app_data(web::Data::new(ml_client.clone()))
            .route("/health", web::get().to(health))
            .configure(handlers::configure)
            .wrap(Logger::new("%a | %r | %s").log_target("http_log"))
            .wrap(cors)
    })
    .bind((config.host.as_str(), config.port))?
    .run()
    .await
}

use reqwest::Client;
use serde::{Deserialize, Serialize};
use crate::errors::AppError;
use crate::models::{MlStatusResponse, MlRetrainResponse};

#[derive(Clone)]
pub struct MlClient {
    base_url: String,
    client: Client,
}

#[derive(Serialize)]
struct PredictRequest {
    summary: String,
    description: Option,
}

#[derive(Deserialize)]
struct PredictResponse {
    predicted_seconds: f64,
}

impl MlClient {
    pub fn new(base_url: String) -> Self {
        Self {
            base_url,
            client: Client::new(),
        }
    }

    pub async fn predict_time(
        &self,
        title: &str,
        description: Option<&str>,
    ) -> Result {
        let request = PredictRequest {
            summary: title.to_string(),
            description: description.map(|s| s.to_string()),
        };

        let response = self
            .client
            .post(format!("{}/predict", self.base_url))
            .json(&request)
            .send()
            .await
            .map_err(|e| {
                tracing::warn!("ML service unavailable: {}", e);
                AppError::Internal("ML service unavailable".to_string())
            })?;

        if !response.status().is_success() {
            tracing::warn!("ML service returned error: {}", response.status());
            return Err(AppError::Internal("ML service error".to_string()));
        }

        let result: PredictResponse = response.json().await.map_err(|e| {
            tracing::warn!("Failed to parse ML response: {}", e);
            AppError::Internal("Invalid ML response".to_string())
        })?;

        Ok(result.predicted_seconds)
    }

    pub async fn predict_time_safe(
        &self,
        title: &str,
        description: Option<&str>,
    ) -> Option {
        self.predict_time(title, description).await.ok()
    }

    pub async fn get_status(&self) -> Result {
        let response = self
            .client
            .get(format!("{}/status", self.base_url))
            .send()
            .await
            .map_err(|e| {
                tracing::warn!("ML service unavailable: {}", e);
                AppError::Internal("ML service unavailable".to_string())
            })?;

        response.json().await.map_err(|e| {
            tracing::warn!("Failed to parse ML status: {}", e);
            AppError::Internal("Invalid ML response".to_string())
        })
    }

    pub async fn trigger_retrain(&self) -> Result {
        let response = self
            .client
            .post(format!("{}/retrain", self.base_url))
            .send()
            .await
            .map_err(|e| {
                tracing::warn!("ML service unavailable: {}", e);
                AppError::Internal("ML service unavailable".to_string())
            })?;

        response.json().await.map_err(|e| {
            tracing::warn!("Failed to parse retrain response: {}", e);
            AppError::Internal("Invalid ML response".to_string())
        })
    }
}

use chrono::{DateTime, Utc}; use serde::{Deserialize, Serialize};
// ============ User ============
#[derive(Debug, Clone, sqlx::FromRow, Serialize)] pub struct User { pub id: i64, pub email: String, #[serde(skip_serializing)] pub password_hash: String, pub name: String, pub role: String, pub created_at: DateTime, }
#[derive(Debug, Deserialize)] pub struct CreateUserRequest { pub email: String, pub password: String, pub name: String, #[serde(default = "default_role")] pub role: String, }
fn default_role() -> String { "member".to_string() }
#[derive(Debug, Deserialize)] pub struct LoginRequest { pub email: String, pub password: String, }
#[derive(Debug, Serialize)] pub struct AuthResponse { pub token: String, pub user: User, }
#[derive(Debug, Deserialize)] pub struct ChangePasswordRequest { pub current_password: String, pub new_password: String, }
// ============ Task ============
#[derive(Debug, Clone, sqlx::FromRow, Serialize)] pub struct Task { pub id: i64, pub title: String, pub description: Option, pub status: String, pub predicted_seconds: Option, pub actual_spent_seconds: Option, pub assignee_id: Option, pub created_by: i64, pub created_at: DateTime, pub updated_at: DateTime, pub completed_at: Option<DateTime>, pub is_archived: bool, }
#[derive(Debug, Clone, Serialize)] pub struct TaskResponse { pub id: i64, pub title: String, pub description: Option, pub status: String, pub predicted_hours: Option, pub actual_hours: Option, pub assignee_id: Option, pub created_by: i64, pub created_at: DateTime, pub updated_at: DateTime, pub completed_at: Option<DateTime>, pub is_archived: bool, }
impl From for TaskResponse { fn from(task: Task) -> Self { Self { id: task.id, title: task.title, description: task.description, status: task.status, predicted_hours: task.predicted_seconds.map(|s| s / 3600.0), actual_hours: task.actual_spent_seconds.map(|s| s / 3600.0), assignee_id: task.assignee_id, created_by: task.created_by, created_at: task.created_at, updated_at: task.updated_at, completed_at: task.completed_at, is_archived: task.is_archived, } } }
#[derive(Debug, Deserialize)] pub struct CreateTaskRequest { pub title: String, pub description: Option, pub assignee_id: Option, }
#[derive(Debug, Deserialize)] pub struct UpdateTaskRequest { pub title: Option, #[serde(default, deserialize_with = "deserialize_optional_field")] pub description: Option<Option>, pub status: Option, #[serde(default, deserialize_with = "deserialize_optional_field")] pub assignee_id: Option<Option>, pub actual_hours: Option, }
fn deserialize_optional_field<'de, T, D>(deserializer: D) -> Result<Option<Option>, D::Error> where T: Deserialize<'de>, D: serde::Deserializer<'de>, { Ok(Some(Option::deserialize(deserializer)?)) }
// ============ Auth context ============
#[derive(Debug, Clone)] pub struct AuthenticatedUser { pub id: i64, pub role: String, }
// =========== Analytics ============
#[derive(Debug, Serialize)] pub struct AnalyticsResponse { pub tasks_by_status: TasksByStatus, pub tasks_by_user: Vec, pub prediction_accuracy: Vec, pub avg_time_by_user: Vec, }
#[derive(Debug, Serialize)] pub struct TasksByStatus { pub todo: i64, pub in_progress: i64, pub done: i64, }
#[derive(Debug, Serialize)] pub struct UserTaskStats { pub user_id: i64, pub user_name: String, pub todo: i64, pub in_progress: i64, pub done: i64, }
#[derive(Debug, Serialize)] pub struct PredictionPoint { pub task_id: i64, pub predicted_hours: f64, pub actual_hours: f64, }
#[derive(Debug, Serialize)] pub struct UserAvgTime { pub user_id: i64, pub user_name: String, pub avg_hours: f64, pub task_count: i64, }
// =========== ML ============ #[derive(Debug, Serialize, Deserialize)] pub struct MlStatusResponse { pub active_model: Option, pub model_candidate_id: Option, pub activated_at: Option, pub r2_val: Option, pub medae_val: Option, pub mdape_val: Option, }
#[derive(Debug, Serialize, Deserialize)] pub struct MlRetrainResponse { pub status: String, pub run_id: i64, pub best_model: Option, pub metrics_val: Option, pub metrics_test: Option, pub activated: bool, pub message: Option, }

use sqlx::SqlitePool;
use chrono::Utc;
use crate::models::{
    User, Task, CreateTaskRequest, UpdateTaskRequest,
    TasksByStatus, UserTaskStats, PredictionPoint, UserAvgTime,
};
use crate::errors::AppError;

// ============ Users ============

pub async fn create_user(
    pool: &SqlitePool,
    email: &str,
    password_hash: &str,
    name: &str,
    role: &str,
) -> Result {
    sqlx::query_as::(
        r#"
        INSERT INTO users (email, password_hash, name, role)
        VALUES (?, ?, ?, ?)
        RETURNING *
        "#
    )
    .bind(email)
    .bind(password_hash)
    .bind(name)
    .bind(role)
    .fetch_one(pool)
    .await
    .map_err(|e| {
        if e.to_string().contains("UNIQUE") {
            AppError::BadRequest("Email already exists".to_string())
        } else {
            e.into()
        }
    })
}

pub async fn get_user_by_id(pool: &SqlitePool, id: i64) -> Result {
    sqlx::query_as::("SELECT * FROM users WHERE id = ?")
