}

pub async fn get_all_active_tasks(pool: &SqlitePool) -> Result<Vec, AppError> {
    Ok(sqlx::query_as::(
        "SELECT * FROM tasks WHERE is_archived = 0 ORDER BY created_at DESC"
    )
    .fetch_all(pool)
    .await?)
}

pub async fn get_tasks_by_assignee(pool: &SqlitePool, user_id: i64) -> Result<Vec, AppError> {
    Ok(sqlx::query_as::(
        "SELECT * FROM tasks WHERE assignee_id = ? AND is_archived = 0 ORDER BY created_at DESC"
    )
    .bind(user_id)
    .fetch_all(pool)
    .await?)
}

pub async fn update_task(
    pool: &SqlitePool,
    id: i64,
    req: &UpdateTaskRequest,
) -> Result {
    let current = get_task_by_id(pool, id).await?;

    let new_description = match &req.description {
        Some(desc) => desc.clone(),
        None => current.description,
    };

    let new_assignee = match &req.assignee_id {
        Some(id) => *id,
        None => current.assignee_id,
    };

    let new_status = req.status.as_ref().unwrap_or(&current.status);

    let new_actual_seconds = req.actual_hours
        .map(|h| h * 3600.0)
        .or(current.actual_spent_seconds);

    let new_completed_at = if new_status == "done" && current.status != "done" {
        Some(Utc::now())
    } else if new_status != "done" {
        None
    } else {
        current.completed_at
    };

    sqlx::query_as::(
        r#"
        UPDATE tasks
        SET title = ?, description = ?, status = ?,
            assignee_id = ?, actual_spent_seconds = ?,
            completed_at = ?, updated_at = CURRENT_TIMESTAMP
        WHERE id = ?
        RETURNING *
        "#
    )
    .bind(req.title.as_ref().unwrap_or(&current.title))
    .bind(&new_description)
    .bind(new_status)
    .bind(new_assignee)
    .bind(new_actual_seconds)
    .bind(new_completed_at)
    .bind(id)
    .fetch_one(pool)
    .await
    .map_err(|e| e.into())
}

pub async fn delete_task(pool: &SqlitePool, id: i64) -> Result<(), AppError> {
    let result = sqlx::query("DELETE FROM tasks WHERE id = ?")
        .bind(id)
        .execute(pool)
        .await?;

    if result.rows_affected() == 0 {
        return Err(AppError::NotFound("Task not found".to_string()));
    }
    Ok(())
}

pub async fn archive_completed_tasks(pool: &SqlitePool) -> Result {
    let result = sqlx::query(
        "UPDATE tasks SET is_archived = 1 WHERE status = 'done' AND is_archived = 0"
    )
    .execute(pool)
    .await?;
    Ok(result.rows_affected())
}

// ============ Analytics ============

pub async fn get_tasks_by_status_counts(pool: &SqlitePool) -> Result {
    let rows: Vec<(String, i64)> = sqlx::query_as(
        "SELECT status, COUNT(*) FROM tasks WHERE is_archived = 0 GROUP BY status"
    )
    .fetch_all(pool)
    .await?;

    let mut stats = TasksByStatus { todo: 0, in_progress: 0, done: 0 };
    for (status, count) in rows {
        match status.as_str() {
            "todo" => stats.todo = count,
            "in_progress" => stats.in_progress = count,
            "done" => stats.done = count,
            _ => {}
        }
    }
    Ok(stats)
}

pub async fn get_tasks_by_user_counts(pool: &SqlitePool) -> Result<Vec, AppError> {
    let rows: Vec<(i64, String, String, i64)> = sqlx::query_as(
        r#"
        SELECT u.id, u.name, t.status, COUNT(*)
        FROM tasks t
        JOIN users u ON t.assignee_id = u.id
        WHERE t.is_archived = 0
        GROUP BY u.id, u.name, t.status
        ORDER BY u.name
        "#
    )
    .fetch_all(pool)
    .await?;

    let mut map: std::collections::HashMap = std::collections::HashMap::new();
    for (uid, name, status, count) in rows {
        let entry = map.entry(uid).or_insert(UserTaskStats {
            user_id: uid,
            user_name: name,
            todo: 0,
            in_progress: 0,
            done: 0,
        });
        match status.as_str() {
            "todo" => entry.todo = count,
            "in_progress" => entry.in_progress = count,
            "done" => entry.done = count,
            _ => {}
        }
    }
    Ok(map.into_values().collect())
}

pub async fn get_prediction_accuracy(pool: &SqlitePool) -> Result<Vec, AppError> {
    Ok(sqlx::query_as::(
        r#"
        SELECT id, predicted_seconds, actual_spent_seconds
        FROM tasks
        WHERE status = 'done'
          AND predicted_seconds IS NOT NULL
          AND actual_spent_seconds IS NOT NULL
          AND actual_spent_seconds > 0
        "#
    )
    .fetch_all(pool)
    .await?
    .into_iter()
    .map(|(id, pred, actual)| PredictionPoint {
        task_id: id,
        predicted_hours: pred / 3600.0,
        actual_hours: actual / 3600.0,
    })
    .collect())
}

pub async fn get_avg_time_by_user(pool: &SqlitePool) -> Result<Vec, AppError> {
    Ok(sqlx::query_as::(
        r#"
        SELECT u.id, u.name,
               AVG(t.actual_spent_seconds) / 3600.0,
               COUNT(*)
        FROM tasks t
        JOIN users u ON t.assignee_id = u.id
        WHERE t.status = 'done'
          AND t.actual_spent_seconds IS NOT NULL
          AND t.actual_spent_seconds > 0
        GROUP BY u.id, u.name
        "#
    )
    .fetch_all(pool)
    .await?
    .into_iter()
    .map(|(id, name, avg, count)| UserAvgTime {
        user_id: id,
        user_name: name,
        avg_hours: avg,
        task_count: count,
    })
    .collect())
}

pub async fn update_prediction(
    pool: &SqlitePool,
    id: i64,
    predicted_seconds: Option,
) -> Result {
    sqlx::query_as::(
        r#"
        UPDATE tasks
        SET predicted_seconds = ?
        WHERE id = ?
        RETURNING *
        "#
    )
    .bind(predicted_seconds)
    .bind(id)
    .fetch_one(pool)
    .await
    .map_err(|e| e.into())
}

use sqlx::SqlitePool;
use crate::auth;
use crate::errors::AppError;
use crate::ml_client::MlClient;
use crate::models::{
    AnalyticsResponse, AuthResponse, ChangePasswordRequest, CreateTaskRequest,
    CreateUserRequest, LoginRequest, MlRetrainResponse, MlStatusResponse,
    TaskResponse, UpdateTaskRequest, User,
};
use crate::repository;

// ============ Init ============

pub async fn init_admin(
    pool: &SqlitePool,
    email: &str,
    password: &str,
) -> Result<(), AppError> {
    let user_count = repository::count_users(pool).await?;

    if user_count > 0 {
        tracing::info!("Database already has users, skipping admin creation");
        return Ok(());
    }

    tracing::info!("Creating initial admin user: {}", email);

    let password_hash = auth::hash_password(password)?;
    repository::create_user(pool, email, &password_hash, "Admin", "admin").await?;

    tracing::info!("Admin user created successfully");
    Ok(())
}

// ============ Auth ============

pub async fn login(
    pool: &SqlitePool,
    req: LoginRequest,
    jwt_secret: &str,
) -> Result {
    let user = repository::get_user_by_email(pool, &req.email)
        .await?
        .ok_or(AppError::Unauthorized)?;

    if !auth::verify_password(&req.password, &user.password_hash)? {
        return Err(AppError::Unauthorized);
    }

    let token = auth::create_token(user.id, &user.role, jwt_secret)?;
    Ok(AuthResponse { token, user })
}

pub async fn change_password(
    pool: &SqlitePool,
    user_id: i64,
    req: ChangePasswordRequest,
) -> Result<(), AppError> {
    let user = repository::get_user_by_id(pool, user_id).await?;

    if !auth::verify_password(&req.current_password, &user.password_hash)? {
        return Err(AppError::BadRequest("Current password is incorrect".to_string()));
    }

    let new_hash = auth::hash_password(&req.new_password)?;
    repository::update_password(pool, user_id, &new_hash).await
}

// ============ Users ============

pub async fn create_user(
    pool: &SqlitePool,
    req: CreateUserRequest,
) -> Result {
    let password_hash = auth::hash_password(&req.password)?;
    repository::create_user(pool, &req.email, &password_hash, &req.name, &req.role).await
}

pub async fn get_all_users(pool: &SqlitePool) -> Result<Vec, AppError> {
    repository::get_all_users(pool).await
}

pub async fn get_user_by_id(pool: &SqlitePool, id: i64) -> Result {
    repository::get_user_by_id(pool, id).await
}

pub async fn delete_user(pool: &SqlitePool, user_id: i64) -> Result<(), AppError> {
    repository::delete_user(pool, user_id).await
}

// ============ Tasks ============

pub async fn create_task(
    pool: &SqlitePool,
    ml_client: &MlClient,
    req: CreateTaskRequest,
    created_by: i64,
) -> Result {
    let predicted_seconds = ml_client
        .predict_time_safe(&req.title, req.description.as_deref())
        .await;

    let task = repository::create_task(pool, &req, created_by, predicted_seconds).await?;
    Ok(task.into())
}

pub async fn get_all_active_tasks(pool: &SqlitePool) -> Result<Vec, AppError> {
    let tasks = repository::get_all_active_tasks(pool).await?;
    Ok(tasks.into_iter().map(|t| t.into()).collect())
}

pub async fn get_my_tasks(pool: &SqlitePool, user_id: i64) -> Result<Vec, AppError> {
    let tasks = repository::get_tasks_by_assignee(pool, user_id).await?;
    Ok(tasks.into_iter().map(|t| t.into()).collect())
}

pub async fn get_task_by_id(pool: &SqlitePool, id: i64) -> Result {
    let task = repository::get_task_by_id(pool, id).await?;
    Ok(task.into())
}

pub async fn update_task(
    pool: &SqlitePool,
    ml_client: &MlClient,
    id: i64,
    req: UpdateTaskRequest,
) -> Result {
    if let Some(ref status) = req.status {
        if !["todo", "in_progress", "done"].contains(&status.as_str()) {
            return Err(AppError::BadRequest(
                "Status must be: todo, in_progress, done".to_string(),
            ));
        }
    }

    // Проверяем изменился ли текст — нужно ли пересчитать предсказание
    let needs_prediction = req.title.is_some() || req.description.is_some();

    let mut task = repository::update_task(pool, id, &req).await?;

    if needs_prediction {
        let predicted_seconds = ml_client
            .predict_time_safe(&task.title, task.description.as_deref())
            .await;

        if predicted_seconds.is_some() {
            task = repository::update_prediction(pool, id, predicted_seconds).await?;
        }
    }

    Ok(task.into())
}

pub async fn delete_task(pool: &SqlitePool, id: i64) -> Result<(), AppError> {
    repository::delete_task(pool, id).await
}

pub async fn archive_completed(pool: &SqlitePool) -> Result {
    repository::archive_completed_tasks(pool).await
}

// ============ Analytics ============

pub async fn get_analytics(pool: &SqlitePool) -> Result {
    let tasks_by_status = repository::get_tasks_by_status_counts(pool).await?;
    let tasks_by_user = repository::get_tasks_by_user_counts(pool).await?;
    let prediction_accuracy = repository::get_prediction_accuracy(pool).await?;
    let avg_time_by_user = repository::get_avg_time_by_user(pool).await?;

    Ok(AnalyticsResponse {
        tasks_by_status,
        tasks_by_user,
        prediction_accuracy,
        avg_time_by_user,
    })
}

// ============ ML Proxy ============

pub async fn get_ml_status(ml_client: &MlClient) -> Result {
    ml_client.get_status().await
}

pub async fn trigger_retrain(ml_client: &MlClient) -> Result {
    ml_client.trigger_retrain().await
}

