use crate::models::*;
use gloo_storage::{LocalStorage, Storage};

const API_URL: &str = "http://localhost:8080/api";
const TOKEN_KEY: &str = "auth_token";

pub fn get_token() -> Option {
    LocalStorage::get(TOKEN_KEY).ok()
}

pub fn set_token(token: &str) {
    let _ = LocalStorage::set(TOKEN_KEY, token);
}

pub fn clear_token() {
    LocalStorage::delete(TOKEN_KEY);
}

fn client() -> reqwest::Client {
    reqwest::Client::new()
}

fn auth_header() -> Result {
    let token = get_token().ok_or("Not authenticated")?;
    Ok(format!("Bearer {}", token))
}

// ============ Auth ============

pub async fn login(email: String, password: String) -> Result {
    let response = client()
        .post(format!("{}/login", API_URL))
        .json(&LoginRequest { email, password })
        .send()
        .await
        .map_err(|e| e.to_string())?;

    if response.status().is_success() {
        let auth: AuthResponse = response.json().await.map_err(|e| e.to_string())?;
        set_token(&auth.token);
        Ok(auth)
    } else {
        Err("Invalid credentials".to_string())
    }
}

// ============ Users ============

pub async fn get_users() -> Result<Vec, String> {
    let response = client()
        .get(format!("{}/users", API_URL))
        .header("Authorization", auth_header()?)
        .send()
        .await
        .map_err(|e| e.to_string())?;

    if response.status().is_success() {
        response.json().await.map_err(|e| e.to_string())
