mod api;
mod models;
mod pages;

use leptos::*;
use pages::{
    login::LoginPage,
    board::BoardPage,
    tasks::TasksPage,
    analytics::AnalyticsPage,
    admin::AdminPage,
};
use crate::models::User;

fn main() {
    console_error_panic_hook::set_once();
    mount_to_body(App);
}

#[derive(Clone, PartialEq)]
enum Page {
    Board,
    Tasks,
    Analytics,
    Admin,
}

#[component]
fn App() -> impl IntoView {
    let (user, set_user) = create_signal(Option::::None);
    let (page, set_page) = create_signal(Page::Board);
    let (users, set_users) = create_signal(Vec::::new());

    // Загрузка пользователей после логина
    create_effect(move |_| {
        if user.get().is_some() {
            spawn_local(async move {
                if let Ok(fetched) = api::get_users().await {
                    set_users.set(fetched);
                }
