use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct User {
    pub id: i64,
    pub email: String,
    pub name: String,
    pub role: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Task {
    pub id: i64,
    pub title: String,
    pub description: Option,
    pub status: String,
    pub predicted_hours: Option,
    pub actual_hours: Option,
    pub assignee_id: Option,
    pub created_by: i64,
    pub is_archived: bool,
}

#[derive(Debug, Clone, Serialize)]
pub struct LoginRequest {
    pub email: String,
    pub password: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct AuthResponse {
    pub token: String,
    pub user: User,
}

#[derive(Debug, Clone, Serialize)]
pub struct CreateTaskRequest {
    pub title: String,
    pub description: Option,
    pub assignee_id: Option,
}

#[derive(Debug, Clone, Serialize)]
pub struct UpdateTaskRequest {
    pub title: Option,
    pub description: Option<Option>,
    pub status: Option,
    pub assignee_id: Option<Option>,
    pub actual_hours: Option,
}

#[derive(Debug, Clone, Serialize)]
pub struct CreateUserRequest {
    pub email: String,
    pub password: String,
    pub name: String,
    pub role: String,
}

// Analytics
#[derive(Debug, Clone, Deserialize)]
pub struct AnalyticsResponse {
    pub tasks_by_status: TasksByStatus,
    pub tasks_by_user: Vec,
    pub prediction_accuracy: Vec,
    pub avg_time_by_user: Vec,
}

#[derive(Debug, Clone, Deserialize)]
pub struct TasksByStatus {
    pub todo: i64,
    pub in_progress: i64,
    pub done: i64,
}

#[derive(Debug, Clone, Deserialize)]
pub struct UserTaskStats {
    pub user_id: i64,
    pub user_name: String,
    pub todo: i64,
    pub in_progress: i64,
    pub done: i64,
}

#[derive(Debug, Clone, Deserialize)]
pub struct PredictionPoint {
    pub task_id: i64,
    pub predicted_hours: f64,
    pub actual_hours: f64,
}

#[derive(Debug, Clone, Deserialize)]
pub struct UserAvgTime {
    pub user_id: i64,
    pub user_name: String,
    pub avg_hours: f64,
    pub task_count: i64,
}

// ML
#[derive(Debug, Clone, Deserialize)]
pub struct MlStatusResponse {
    pub active_model: Option,
    pub model_candidate_id: Option,
    pub activated_at: Option,
    pub r2_val: Option,
    pub medae_val: Option,
    pub mdape_val: Option,
}

#[derive(Debug, Clone, Deserialize)]
pub struct MlRetrainResponse {
    pub status: String,
    pub run_id: i64,
    pub best_model: Option,
    pub metrics_val: Option,
    pub metrics_test: Option,
    pub activated: bool,
    pub message: Option,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ArchiveResponse {
    pub archived: u64,
}

