fn user_name_by_id(users: &[User], user_id: Option) -> String {
    match user_id {
        None => "Unassigned".to_string(),
        Some(id) => users
            .iter()
            .find(|u| u.id == id)
            .map(|u| u.name.clone())
            .unwrap_or_else(|| format!("User #{}", id)),
    }
}

